/bin/zsh -lc "./run_python - <<'PY'
import original, tempfile, pathlib
with tempfile.TemporaryDirectory(dir='.') as d:
    q = original.Queue(pathlib.Path(d) / 'queue.db')
    q.put('bool', [])
    try:
        print('boolean lease:', q.claim('w', 0, True))
    except Exception as e:
        print('boolean lease:', type(e).__name__)
    for depth in range(950, 1010):
        value = 0
        for _ in range(depth):
            value = [value]
        try:
            q.put(str(depth), value)
        except (TypeError, ValueError, RecursionError) as e:
            print('first put rejection:', depth, type(e).__name__)
            break
        try:
            result = q.claim('w', 2, 1)
            q.ack(result['receipt'], 2)
        except Exception as e:
            print('accepted payload cannot be claimed:', depth, type(e).__name__)
            break
PY"

/bin/zsh -lc "./run_python -u - <<'PY'
import original, pathlib, tempfile
with tempfile.TemporaryDirectory(dir='.') as d:
    q = original.Queue(pathlib.Path(d) / 'queue.db')
    value = None
    for depth in range(1, 10010):
        value = [value]
        if depth < 9900:
            continue
        try:
            q.put(str(depth), value)
        except Exception as e:
            print('first put rejection', depth, type(e).__name__)
            break
        try:
            r = q.claim('w', 0, 1)
            assert q.ack(r['receipt'], 0)
        except Exception as e:
            print('accepted payload fails claim', depth, type(e).__name__)
            break
    else:
        print('no failure')
PY"

